target.css:
:root {
  --label-bg: #f0ede4;
  --border-color: #7a9e87;
  --header-color: #2c5f3f;
  --sub-color: #5a8a6a;
  --text-dark: #2d2a1f;
  --text-muted: #7a7060;
  --badge-bg: #2c5f3f;
  --badge-text: #f0ede4;
  --divider-color: #7a9e87;
  --value-color: #4a7a5a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.bottle-label {
  background-color: var(--label-bg);
  border: 3px double var(--border-color);
  border-radius: 12px;
  padding: 20px 28px;
  width: 300px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.label-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.est-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  padding: 2px 10px;
  border-radius: 20px;
}

.spring-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--header-color);
  margin: 0;
  letter-spacing: 1px;
  line-height: 1.2;
}

.spring-sub {
  font-size: 11px;
  font-weight: 500;
  color: var(--sub-color);
  letter-spacing: 3px;
  text-transform: uppercase;
  margin: 0;
}

.divider {
  height: 2px;
  background-color: var(--divider-color);
  border-radius: 2px;
  opacity: 0.4;
}

.label-body {
  padding: 4px 0;
}

.mineral-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.mineral-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.mineral {
  font-size: 13px;
  color: var(--text-dark);
  font-weight: 600;
}

.value {
  font-size: 13px;
  color: var(--value-color);
  font-weight: 500;
}

.label-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.volume {
  font-size: 13px;
  font-weight: 700;
  color: var(--header-color);
}

.origin {
  font-size: 10px;
  color: var(--text-muted);
  font-style: italic;
}

